const homeHeadlineElement=ref<HTMLElement|null>(null)
watch(homeHeadlineElement,(heading,_,onCleanup)=>{
  if(!heading)return
  const content=heading.firstElementChild as HTMLElement
  function fitHeadline(){
    if(!heading.isConnected||!heading.clientWidth)return
    heading.style.removeProperty('font-size')
    const maximum=parseFloat(getComputedStyle(heading).fontSize)
    const fits=()=>content.scrollWidth<=heading.clientWidth&&content.scrollHeight<=heading.clientHeight
    if(fits())return
    let low=0,high=maximum
    for(let step=0;step<12;step++){
      const size=(low+high)/2
      heading.style.fontSize=size+'px'
      if(fits())low=size
      else high=size
    }
    heading.style.fontSize=low+'px'
  }
  const observer=new ResizeObserver(fitHeadline)
  observer.observe(heading)
  fitHeadline()
  void document.fonts.ready.then(fitHeadline)
  onCleanup(()=>observer.disconnect())
})
