async function profileRequest(path:string,method='GET',body?:unknown){const headers:Record<string,string>={};if(body!==undefined)headers['content-type']='application/json';if(!['GET','HEAD'].includes(method))headers['x-csrf-token']=accountCsrfToken.value;const response=await fetch('/api/v1'+path,{method,headers,credentials:'same-origin',body:body===undefined?undefined:JSON.stringify(body)});if(response.status===204)return null;const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error??`HTTP_${response.status}`);return data}
async function loadAccount(){try{const response=await fetch('/api/v1/me',{credentials:'same-origin'});if(response.status===401)return;if(!response.ok)throw new Error('REQUEST_FAILED');const data=await response.json();const csrf=await fetch('/api/v1/auth/csrf',{credentials:'same-origin'});if(!csrf.ok)throw new Error('REQUEST_FAILED');accountCsrfToken.value=(await csrf.json()).csrfToken;account.value=data.user}catch{account.value=null;accountCsrfToken.value=''}finally{accountLoading.value=false}}
onMounted(loadAccount)
function setProfileError(error:unknown){const code=error instanceof Error?error.message:'REQUEST_FAILED';const messages:Record<string,string>={CURRENT_PASSWORD_INVALID:'Текущий пароль указан неверно.',INVALID_INPUT:'Проверьте введённые данные.',AVATAR_TOO_LARGE:'Файл аватара больше 5 MiB.',AVATAR_UNSUPPORTED:'Поддерживаются только JPEG, PNG и WebP.',AVATAR_ANIMATED:'Анимированные изображения не поддерживаются.',AVATAR_BUSY:'Сервер занят обработкой аватаров, повторите попытку.',CSRF_INVALID:'Обновите страницу и повторите действие.',DATABASE_UNAVAILABLE:'Сервер временно не может сохранить изменение.'};profileMessage.value=messages[code]??'Не удалось сохранить изменения. Попробуйте ещё раз.'}
async function saveNickname(){if(profileBusy.value||!account.value)return;profileBusy.value=true;profileMessage.value='';try{account.value=(await profileRequest('/me','PATCH',{displayName:nicknameDraft.value})).user;profileMessage.value='Никнейм сохранён.'}catch(error){setProfileError(error)}finally{profileBusy.value=false}}
async function changePassword(){if(profileBusy.value)return;profileBusy.value=true;profileMessage.value='';try{const data=await profileRequest('/me/password','PUT',{currentPassword:currentPassword.value,newPassword:newPassword.value});accountCsrfToken.value=data.csrfToken;currentPassword.value='';newPassword.value='';profileMessage.value='Пароль изменён. Остальные сеансы завершены.'}catch(error){setProfileError(error)}finally{profileBusy.value=false}}
async function uploadProfileAvatar(event:Event){const input=event.currentTarget as HTMLInputElement;const file=input.files?.[0];if(!file||!account.value||profileBusy.value)return;if(file.size>5*1024*1024){setProfileError(new Error('AVATAR_TOO_LARGE'));input.value='';return}if(avatarPreview.value.startsWith('blob:'))URL.revokeObjectURL(avatarPreview.value);avatarPreview.value=URL.createObjectURL(file);profileBusy.value=true;profileMessage.value='';const form=new FormData();form.append('file',file);try{const response=await fetch('/api/v1/me/avatar',{method:'PUT',credentials:'same-origin',headers:{'x-csrf-token':accountCsrfToken.value},body:form});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error??`HTTP_${response.status}`);account.value={...account.value,avatarUrl:data.avatarUrl,avatarVersion:data.avatarVersion};if(avatarPreview.value.startsWith('blob:'))URL.revokeObjectURL(avatarPreview.value);avatarPreview.value='';profileMessage.value='Аватар обновлён.'}catch(error){setProfileError(error)}finally{input.value='';profileBusy.value=false}}
