async function confirmDeleteDeck(){const target=deckToDelete.value;if(!target||deckLibraryBusy.value)return;deckLibraryBusy.value=true;deckLibraryError.value='';try{await profileRequest(`/decks/${target.id}?expectedRevision=${target.revision}`,'DELETE');savedDecks.value=savedDecks.value.filter(deck=>deck.id!==target.id);deckToDelete.value=null}catch{deckLibraryError.value='Не удалось удалить колоду. Обновите список и попробуйте ещё раз.'}finally{deckLibraryBusy.value=false}}
