const at=(r:number,c:number)=>board.value.find(u=>u.row===r&&u.col===c)
const note=(text:string)=>{log.value=[text,...log.value].slice(0,7)}
const coord=(row:number,col:number)=>`${['А','Б','В','Г','Д'][row] ?? '?'}${col+1}`
const unitDescription=(u:Unit)=>effectiveCardDescription(u.card.Description,u.item?.Description)
const unitHas=(u:Unit,keyword:string)=>keyword==='Ярость'?hasTemporaryRage(unitDescription(u),u.temporaryRage):unitDescription(u).includes(keyword)
function detachItem(unit:Unit){const item=unit.item;if(!item)return;unit.item=undefined;unit.nextAttackNegated=Boolean(rulesForCard(unit.card.Name).negateNextAttack);unit.attack-=item.Attack;unit.maxHealth-=item.Health;unit.health=Math.min(unit.health,unit.maxHealth);for(const effect of effectsWhenEquipped(item.Name)){if(effect.kind==='decrease-hand-limit')updateHandLimit(players.value[unit.owner],effect.amount);else if(effect.kind==='change-attack')unit.attack-=effect.amount}return item}
function transferItem(unit:Unit,item:Card|null,donor?:Unit){if(item&&unit.item)return false;if(donor&&donor.item!==item)return false;if(donor)detachItem(donor);if(!item){const removed=detachItem(unit);if(removed)players.value[unit.owner].discard.push(removed);return !!removed}unit.item=item;unit.nextAttackNegated=Boolean(rulesForCard(item.Name).negateNextAttack);unit.attack+=item.Attack;unit.health+=item.Health;unit.maxHealth+=item.Health;if(itemGrantsShield(item.Description))unit.shield=true;for(const effect of effectsWhenEquipped(item.Name)){if(effect.kind==='decrease-hand-limit')updateHandLimit(players.value[unit.owner],-effect.amount);else if(effect.kind==='change-attack')unit.attack+=effect.amount}return true}
const inform=(text:string)=>{toast.value=text; window.setTimeout(()=>{if(toast.value===text)toast.value=''},2500)}
const visual=(kind:string)=>{toast.value='';effectKind.value=kind;effectTick.value++;window.setTimeout(()=>{if(effectKind.value===kind)effectKind.value=''},720)}
const unitEffects=ref<Record<string,Record<string,number>>>({})
const unitVisual=(u:Unit,kind:string)=>{const effects=unitEffects.value[u.id]??(unitEffects.value[u.id]={}),tick=(effects[kind]??0)+1;effects[kind]=tick;window.setTimeout(()=>{if(effects[kind]===tick){delete effects[kind];if(!Object.keys(effects).length)delete unitEffects.value[u.id]}},680)}
const cardImageError=(event:Event)=>{(event.currentTarget as HTMLImageElement).src='/card_back.png'}
const shuffle=<T>(a:T[])=>[...a].sort(()=>Math.random()-.5)
watch(screen,value=>{if(value==='start'){homeCards.value=shuffle(cards).slice(0,4);homeCard.value=homeCards.value[0]!}},{immediate:true})
const adjacent=(u:Unit,r:number,c:number,diagonal=false)=>canMoveTo(u.row,u.col,r,c,diagonal)
const canMove=(u:Unit,r:number,c:number)=>!unitMovementBlocked(u)&&unitCanMoveAndAttack(u,board.value)&&canMoveTo(u.row,u.col,r,c,u.item?.Name==='Банни хоп')
const active=(u:Unit)=>u.owner===current.value&&!u.dying&&!u.stunned&&(!u.flippedTurns||canActWhileFlipped(unitDescription(u)))&&(u.card.Type===3||u.summoned<round.value||unitHas(u,'Порыв')||board.value.some(x=>x.owner===u.owner&&x.card.Name==='Вечная ночь'&&!x.dying))
const abilityCost=(u:Unit,index=0)=>abilityCostOnField(unitDescription(u),index,u.owner,board.value)
const canPayAbility=(u:Unit,cost:number,index=0)=>abilityCostResource(unitDescription(u),index)==='black-token'?u.blackTokens>=cost:player.value.mana>=cost
const payAbility=(u:Unit,cost:number,index=0)=>{if(abilityCostResource(unitDescription(u),index)==='black-token')u.blackTokens-=cost;else player.value.mana-=cost}
const isHome=(row:number,owner:number)=>row===(owner?0:4)
const spellNeedsTarget=(card:Card)=>card.Name!=='Додеп'&&card.Name!=='Гнилое ворьё'&&card.Name!=='Лазанья'&&card.Name!=='@everyone'&&card.Name!=='Починка'&&card.Name!=='Перепись населения'&&card.Name!=='Засадка пустыни пшеницей'&&card.Name!=='Ого какой большой огурец'&&card.Name!=='Разбан'&&card.Name!=='Подстава'&&!spellAuctionsCreatures(card.Description)&&!(card.Name==='Half-life 3'&&!board.value.some(unit=>unit.flippedTurns>0&&!unit.dying))&&globalFlipTurns(card.Description)===null&&!globalHealingOperation(card.Description)&&playerHealAmount(card.Description)===null&&!/Нанесите\s+\d+\s+урон(?:а)?\s+всем\s+существам\s+на\s+поле/u.test(card.Description)&&!/(?:Сожгите\s+всех\s+существ\s+на\s+поле|Уничтожьте\s+все\s+перевёрнутые\s+карты)/iu.test(card.Description)&&!card.Description.includes('Восстановите себе')&&!/Возьмите\s+\d*\s*карт(?:у|ы)?/u.test(card.Description)&&!(card.Description.includes('противнику')&&/Нанесите (\d+) урона/.test(card.Description))
function clownTargetRequired(owner:number,target:Unit|undefined,effectText:string,selected:Unit[]=[],remainingSlots=1){if(!effectCanTargetEnemy(effectText))return false;const clowns=board.value.filter(x=>x.owner!==owner&&unitHas(x,'Клоун')&&!x.dying&&!x.flippedTurns);const legalClowns=clowns.filter(x=>targetMatchesKind(x.card.Type,targetKindInDescription(effectText)));if(/существам\s+на\s+линии/iu.test(effectText))return Boolean(target&&legalClowns.length&&!legalClowns.some(x=>x.row===target.row||x.col===target.col));const unselected=legalClowns.filter(x=>!selected.some(chosen=>chosen.id===x.id)).length;return target?mustChooseRemainingClown(unitHas(target,'Клоун'),unselected,remainingSlots):unselected>0}
function canChoosePlayer(target:Player){const card=selectedCard.value;return target===enemy.value&&selection.value?.kind==='hand'&&card?.Type===2&&spellNeedsTarget(card)&&(effectCanTargetPlayer(card.Description)||spellCanTargetPlayer(card.Description)||card.Name==='Дискорд драма'&&discordDramaEffect(card.Description,0,'player',player.value.hand.length,player.value.nextScoreAdjustment).canTargetPlayer)&&!clownTargetRequired(current.value,undefined,card.Description)}
function canEntryChoosePlayer(target:Player){const choice=selection.value,source=choice?.kind==='entry'&&board.value.find(unit=>unit.id===choice.id),owner=choice?.kind==='entry'?(choice.owner??source?.owner??current.value):current.value;return Boolean(source&&target===players.value[1-owner]&&entryCanTargetPlayer(unitDescription(source),source.row,owner)&&!clownTargetRequired(owner,undefined,unitDescription(source)))}
function canAbilityChoosePlayer(target:Player){if(selection.value?.kind!=='ability')return false;const unit=board.value.find(x=>x.id===selection.value?.id),index=selection.value.abilityIndex||0;return Boolean(unit&&target===players.value[1-unit.owner]&&abilityCanTargetPlayer(unitDescription(unit),index,unit.row===enemyRow.value,unit.card.Name)&&!clownTargetRequired(unit.owner,undefined,abilityDescription(unitDescription(unit),index)))}
function clickPlayerTarget(target:Player){if(pendingCardPayment.value||pendingDiscordDrama.value||pendingStartTurnBurns.value)return;if(overLimit.value)return inform('Сначала сбросьте лишние карты.');if(selection.value?.kind==='entry'&&canEntryChoosePlayer(target))return resolveEntryPlayer(selection.value.id,target,selection.value.owner);if(selection.value?.kind==='ability'){const unit=board.value.find(x=>x.id===selection.value?.id),index=selection.value.abilityIndex||0;if(unit&&target===players.value[1-unit.owner]&&abilityCanTargetPlayer(unitDescription(unit),index,unit.row===enemyRow.value,unit.card.Name)&&!clownTargetRequired(unit.owner,undefined,abilityDescription(unitDescription(unit),index)))return resolveAbility(unit.id,-1,-1,undefined,index,target);return inform('Целью здоровье противника может быть только способность карты на его стартовом ряду.')}if(selection.value?.kind==='hand'&&canChoosePlayer(target))play(selection.value.index,-1,-1,undefined,target)}
function canPush(row:number,col:number){if(movementIsBlocked(movementLock.value,current.value))return false;const dir=current.value?1:-1;let r=row;while(r>=0&&r<5){const target=at(r,col);if(!target)break;if(target.card.Type===3||unitMovementBlocked(target)||!unitCanMoveAndAttack(target,board.value))return false;r+=dir}return r>=0&&r<5}
function validHandSlot(row:number,col:number){const card=handTargetCard.value;if(!card)return false;if(card.Name==='Лазанья')return true;const target=at(row,col);if(card.Type===0)return isHome(row,current.value)&&(!target||canPush(row,col));if(card.Type===3)return row!==0&&row!==4&&!target;if(card.Type===1)return !!target&&!target.flippedTurns&&target.card.Type===0&&!target.item;return card.Name==='Лазанья'?!!target:spellNeedsTarget(card)?!!target&&!target.flippedTurns:!target?.flippedTurns}

function initializePlayers(decks:Card[][]):Player[] {
  const match=createMatch({matchId:'local',catalog:cards,players:decks.map((deck,index)=>({userId:`local-${index}`,displayName:`Игрок ${index+1}`,deck:deck.map(card=>card.Id)}))})
  return match.players.map(player=>({name:player.name,health:player.health,mana:player.mana,energy:player.energy,limit:player.limit,deck:player.deck as Card[],hand:player.hand as Card[],discard:[],burned:[],saved:[],played:false,burnedThisTurn:false,nextScoreAdjustment:0}))
}
function begin(){localTurnStartResolved.value=false;localTurnHandSize.value=0;initialLocalTurnPending.value=true;localCoreChoice.value=null;pendingIcebergAbility.value=null;scoreAdjustmentUnit.value=null;void loadGameCore();attackResolution.value=createAttackResolutionState<Unit>();players.value=initializePlayers(builtDecks.value);board.value=[];wheatTokens.value=[];pendingHighCostSearch.value=null;pendingBurnedSearch.value=null;pendingDiscordDrama.value=null;pendingBurnFlipped.value=[];pendingCrownMove.value=null;pendingDedrubi.value=[];pendingSentCroix.value=[];pendingDrone.value=[];pendingSwarmChoice.value=[];pendingZnakSave.value=null;pendingDodep.value=null;pendingIndigolit.value=null;pendingIntivi.value=[];pendingConveyor.value=null;pendingVismuthChoice.value=[];pendingLibrarianChoice.value=null;pendingHedgehogTargets.value=[];movementLock.value=null;current.value=0;round.value=1;log.value=['Партия готова. Игрок 1 открывает первый раунд.'];selection.value=null;screen.value='handoff'}
function copiesOf(card:Card){return deck.value.filter(item=>item.Name===card.Name).length}
function addToDeck(card:Card){if(card.Tags?.includes('в разработке'))return deckMessage.value='Эта карта помечена «в разработке» и пока недоступна для колоды.';if(deck.value.length>=30)return deckMessage.value='В колоде уже 30 карт.';if(card.Rarity<2&&copiesOf(card)>=2)return deckMessage.value='Обычные и редкие карты можно взять максимум в двух экземплярах.';const classes=new Set([...deckClasses.value,card.Class]);if(classes.size>2)return deckMessage.value='В колоде может быть только один или два типажа.';deck.value.push(card);deckMessage.value=''}
function removeFromDeck(card:Card){const index=deck.value.findIndex(item=>item.Name===card.Name);if(index>=0)deck.value.splice(index,1);deckMessage.value=''}
function resetDeck(){deck.value=[];deckMessage.value='Колода сброшена. Перетащите карты из каталога в область слева.'}
function startCardDrag(event:DragEvent,card:Card){draggedCard.value=card;draggedFromDeck.value=false;deckDropActive.value=true;event.dataTransfer?.setData('text/plain',card.Id);if(event.dataTransfer)event.dataTransfer.effectAllowed='copy'}
function startDeckCardDrag(event:DragEvent,card:Card){draggedCard.value=card;draggedFromDeck.value=true;trashDropActive.value=true;event.dataTransfer?.setData('text/plain',card.Id);if(event.dataTransfer)event.dataTransfer.effectAllowed='move'}
function endCardDrag(){draggedCard.value=null;draggedFromDeck.value=false;deckDropActive.value=false;trashDropActive.value=false}
function dropCardIntoDeck(){if(draggedCard.value&&!draggedFromDeck.value)addToDeck(draggedCard.value);endCardDrag()}
function dropCardToTrash(){if(draggedCard.value&&draggedFromDeck.value){removeFromDeck(draggedCard.value);deckMessage.value=`Одна копия «${draggedCard.value.Name}» выброшена из колоды.`}endCardDrag()}
function draw(p:Player,fromHandLimit=false){const card=p.deck.shift();if(card){p.hand.push(card);if(!fromHandLimit)queueBranchTargets(players.value.indexOf(p))}}
function queueVismuthSelection(ownerIndex:number){const owner=players.value[ownerIndex],cards=[takeAndShufflePileCard(owner.deck,1),takeAndShufflePileCard(owner.deck,3)].filter((card):card is Card=>Boolean(card));if(cards.length===2)pendingVismuthChoice.value.push({owner:ownerIndex,cards});else if(cards.length===1)owner.hand.push(cards[0]!);else note('«Висмут Шифера»: в КД не найдено ни предмета, ни здания.')}
function chooseVismuthCard(index:number){const pending=pendingVismuthChoice.value[0],owner=pending&&players.value[pending.owner];if(!pending||!owner||!Number.isInteger(index)||index<0||index>1)return;owner.discard.push(pending.cards[index]!);owner.hand.push(pending.cards[1-index]!);pendingVismuthChoice.value.shift();note(`«Висмут Шифера»: «${pending.cards[index]!.Name}» сброшена, «${pending.cards[1-index]!.Name}» оставлена в руке.`)}
function chooseLibrarianCost(cost:number){const pending=pendingLibrarianChoice.value,owner=pending&&players.value[pending.owner],source=pending&&board.value.find(unit=>unit.id===pending.unitId);if(!pending||pending.stage!=='cost'||!owner||!source||source.dying||source.abilityUsed||![1,2,4].includes(cost)||owner.mana<cost)return inform('Выберите доступную оплату 1, 2 или 4 маны.');const rarity=cost===1?0:cost===2?1:2;if(!owner.deck.some(card=>card.Rarity===rarity)&&!owner.discard.some(card=>card.Rarity===rarity))return inform('В КД и КС нет карт этой редкости.');pending.cost=cost as 1|2|4;pending.stage='pile';inform('Выберите КД или КС для поиска карты нужной редкости.')}
function chooseLibrarianPile(pile:'deck'|'discard'){const pending=pendingLibrarianChoice.value,owner=pending&&players.value[pending.owner],rarity=pending?.cost===1?0:pending?.cost===2?1:2;if(!pending||pending.stage!=='pile'||!owner||!pending.cost||(pile!=='deck'&&pile!=='discard')||!owner[pile].some(card=>card.Rarity===rarity))return inform('В выбранной колоде нет карты нужной редкости.');pending.pile=pile;pending.stage='card';inform('Выберите карту нужной редкости.')}
function chooseLibrarianCard(index:number){const pending=pendingLibrarianChoice.value,owner=pending&&players.value[pending.owner],source=pending&&board.value.find(unit=>unit.id===pending.unitId),pile=pending?.pile,card=owner&&pile?owner[pile][index]:undefined,rarity=pending?.cost===1?0:pending?.cost===2?1:2;if(!pending||pending.stage!=='card'||!owner||!source||source.dying||source.abilityUsed||!pending.cost||!pile||!card||card.Rarity!==rarity||owner.mana<pending.cost)return inform('Выберите доступную карту нужной редкости.');owner[pile].splice(index,1);if(pile==='deck')owner.deck=shuffle(owner.deck);owner.mana-=pending.cost;source.abilityUsed=!isRepeatableAbility(unitDescription(source),pending.abilityIndex);pendingLibrarianChoice.value=null;const roll=rollGamba(owner,gambaModifierForUnit(source));if(roll<=3){const burned=recordBurn(owner,card);if(burned&&pending.owner===current.value)owner.burnedThisTurn=true;note(`«Библиотекарь»: гамба ${roll}; «${card.Name}» ${burned?'сожжена':'сберегается вместо сжигания'}.`)}else{owner.hand.push(card);note(`«Библиотекарь»: гамба ${roll}; «${card.Name}» взята в руку.`)}visual('spell')}
function queueHedgehogTarget(source:Unit){const canTargetOpponent=source.row===(source.owner===0?0:4),hasCardTarget=board.value.some(target=>target.id!==source.id&&!target.dying);if(!hasCardTarget&&!canTargetOpponent)return note('«Ёжик»: после смерти нет допустимой цели.');pendingHedgehogTargets.value.push({source,owner:source.owner,row:source.row})}
function chooseHedgehogTarget(targetId?:string,playerTarget?:number){const pending=pendingHedgehogTargets.value[0];if(!pending)return;if(playerTarget!==undefined){if(playerTarget!==1-pending.owner||pending.row!==(pending.owner===0?0:4))return inform('Противник может быть целью только с его стартового ряда.');hitPlayer(players.value[playerTarget],1);note('«Ёжик» наносит противнику 1 урон.')}else{const target=board.value.find(unit=>unit.id===targetId&&unit.id!==pending.source.id&&!unit.dying);if(!target)return inform('Выберите живую карту на поле.');damage(target,1,{killer:pending.source});if(!target.dying)Object.assign(target,applyCombatStatChanges(target,-1,0));note(`«Ёжик» наносит «${target.card.Name}» 1 урон и накладывает −1 к атаке.`)}pendingHedgehogTargets.value.shift()}
function chooseConveyorCard(index:number){const pending=pendingConveyor.value,owner=pending&&players.value[pending.owner],card=owner?.hand[index];if(!pending||!owner||!card)return;owner.hand.splice(index,1);if(pending.stage==='discard'){owner.discard.push(card);pending.stage='burn';return inform('Выберите карту из руки для сжигания.')}if(pending.stage==='burn'){const burned=recordBurn(owner,card);if(burned&&pending.owner===current.value)owner.burnedThisTurn=true;pending.stage='save';return inform('Выберите карту из руки для сбережения.')}owner.saved.push(card);pendingConveyor.value=null;draw(owner);selection.value=null;note('«Конвейерное производство»: карта сброшена, карта сожжена, карта сбережена и взята карта из КД.')}
function applyGendaBossBuff(unit:Pick<Unit,'attack'|'health'|'maxHealth'|'speed'>,stacks=1){unit.attack+=2*stacks;unit.health+=2*stacks;unit.maxHealth+=2*stacks;unit.speed-=stacks}
function resolveGendaBossSpell(index:number){const owner=player.value;owner.gendaBossStacks=(owner.gendaBossStacks??0)+1;board.value.filter(unit=>unit.owner===current.value&&unit.card.Type===0&&!unit.dying).forEach(unit=>applyGendaBossBuff(unit));hitPlayer(owner,30);finishSpell(index,'Вы получаете 30 урона; ваши существа получают +2 к атаке, +2 к здоровью и +1 к скорости.')}
function grantHameleonewEntry(owner:Player){owner.nextBurnToSave=(owner.nextBurnToSave??0)+1;note('«Hameleonew»: следующая сжигаемая вами карта будет сбережена.')}
function grantBirdliGambaBonus(owner:Player){owner.nextGambaBonus=(owner.nextGambaBonus??0)+2;note('«Бёрдли»: следующая гамба владельца получает +2.')}
function rollGamba(owner:Player,modifier=0){const result=adjustGambaRoll(Math.floor(Math.random()*6)+1,modifier+(owner.nextGambaBonus??0));owner.nextGambaBonus=0;return result}
function resolveNewcomersDeath(owner:number){const player=players.value[owner];if(round.value<10){player.energy+=3;return}if(player.hand.some(card=>card.Type===2)){pendingNewcomers.value=owner;inform('«Новички»: выберите заклинание из руки, чтобы сберечь его.')}}
function updateHandLimit(owner:Player,amount:number){if(owner.depressiveHandLimit)return;const override=owner.temporaryLimitOverride;if(override){override.previous=Math.max(1,override.previous+amount);owner.limit=override.value}else owner.limit=Math.max(1,owner.limit+amount)}
function addTemporaryHandLimit(owner:Player,amount:number,expiresAt:number){if(owner.depressiveHandLimit)return;owner.temporaryLimitExpirations??=[];for(let i=0;i<amount;i++)owner.temporaryLimitExpirations.push(expiresAt);if(!owner.temporaryLimitOverride)owner.limit+=amount}
function setTemporaryHandLimit(owner:Player,value:number,expiresAt:number){if(owner.depressiveHandLimit)return;owner.temporaryLimitExpirations??=[];const override=owner.temporaryLimitOverride,previous=override?.previous??Math.max(1,owner.limit-owner.temporaryLimitExpirations.length);owner.temporaryLimitOverride={previous,value,expiresAt:Math.max(expiresAt,override?.expiresAt??0)};owner.limit=value}
function expireHandLimitEffects(owner:Player,turnIndex:number){const expired=expireTemporaryHandLimit(owner.temporaryLimitExpirations??[],turnIndex);if(owner.depressiveHandLimit){const locked=owner.depressiveHandLimit;if(locked.override&&locked.override.expiresAt<=turnIndex)delete locked.override;owner.limit=1;return}const override=owner.temporaryLimitOverride;if(override){if(override.expiresAt<=turnIndex){owner.limit=Math.max(1,override.previous+(owner.temporaryLimitExpirations?.length??0));delete owner.temporaryLimitOverride}else owner.limit=override.value}else owner.limit=Math.max(1,owner.limit-expired)}
function discardEntireHand(owner:Player){for(const card of [...owner.hand]){const index=owner.hand.indexOf(card);if(index>=0)takeCardFromHand(owner.hand,owner.discard,owner.burned,index,'discard',amount=>heal(owner,amount),count=>{for(let i=0;i<count;i++)draw(owner)},burned=>recordBurn(owner,burned))}}
function resolveDepressiveJawEntry(owner:Player){discardEntireHand(owner);enterDepressiveHandLimit(owner);note('«Депрессивная Жопа» сбрасывает руку и устанавливает лимит в 1.')}
function resolveDepressiveJawStartTurn(owner:Player){const card=takeTopDiscard(owner.discard);if(card)owner.hand.push(card);note(card?`«Депрессивная Жопа» берёт «${card.Name}» из КС.`:'КС пуста: «Депрессивная Жопа» не берёт карту.')}
function enterDepressiveHandLimit(owner:Player){if(owner.depressiveHandLimit)return;const override=owner.temporaryLimitOverride;owner.depressiveHandLimit={previous:override?.previous??Math.max(1,owner.limit-(owner.temporaryLimitExpirations?.length??0)),...(override?{override:{...override}}:{})};delete owner.temporaryLimitOverride;owner.limit=1}
function releaseDepressiveHandLimit(owner:Player){if(board.value.some(unit=>unit.owner===players.value.indexOf(owner)&&unit.card.Name==='Депрессивная Жопа'))return;const locked=owner.depressiveHandLimit;if(!locked)return;const override=locked.override;if(override&&override.expiresAt>(round.value-1)*2+current.value){owner.temporaryLimitOverride=override;owner.limit=override.value}else{delete owner.temporaryLimitOverride;owner.limit=Math.max(1,(override?.previous??locked.previous)+(owner.temporaryLimitExpirations?.length??0))}delete owner.depressiveHandLimit}
watch(board,()=>{players.value.forEach(releaseDepressiveHandLimit);board.value.forEach(resolveTauCannon)},{deep:true})
function resolveWonderTianEntry(unit:Unit,owner:Player){const size=entryDrawToHandSize(unitDescription(unit));if(size===null)return false;let drawn=0;while(owner.hand.length<size&&owner.deck.length){draw(owner);drawn++}const expiresAt=(round.value-1)*2+current.value+2;setTemporaryHandLimit(owner,size,expiresAt);note(`«Вондертян»: добор ${drawn} карт; лимит руки равен ${size} до конца следующего хода.`);return true}
function queueViskassChoice(owner:number,description:string,trigger:'entry'|'crown'){const p=players.value[owner];if(!description.includes('Возьмите или сбросьте карту')||trigger==='crown'&&!scoreConditionMet(description,p.hand.length)||!p.deck.length&&!p.hand.length)return false;pendingViskassChoice.value={owner,selectingDiscard:false};return true}
