function chooseSwarmReward(drawCard:boolean){const owner=pendingSwarmChoice.value.shift();if(owner===undefined)return;if(drawCard)draw(players.value[owner]);else players.value[owner].mana++;note(drawCard?'«Загребущий рой»: взята карта.':'«Загребущий рой»: получена 1 мана.')}
