function chooseZnakSavedCard(index:number){const owner=pendingZnakSave.value,card=owner===null?undefined:players.value[owner].hand[index];if(owner===null||!card)return;players.value[owner].hand.splice(index,1);players.value[owner].saved.push(card);pendingZnakSave.value=null;note(`«Знаком по ебалу» сберегает «${card.Name}» из руки.`)}
function queueDodepReward(owner:number){if(!players.value[owner].hand.length){note('«Додеп»: в руке нет карты для сжигания.');return}pendingDodep.value={owner,amount:null,cardIndex:null}}
function chooseDodepCard(index:number){const pending=pendingDodep.value,owner=pending&&players.value[pending.owner],card=owner?.hand[index];if(!pending||pending.amount!==null||!owner||!card)return;owner.hand.splice(index,1);const burned=recordBurn(owner,card);if(burned&&pending.owner===current.value)owner.burnedThisTurn=true;pending.cardIndex=index;pending.amount=rollGamba(owner);note(`«Додеп»: карта сожжена; выпало ${pending.amount}.`)}
