function playCrownSavedSpell(index:number){const pending=pendingCrownSavedSpell.value,owner=pending&&players.value[pending.owner],card=owner?.saved[index];if(!pending||pending.cardId||pending.owner!==current.value||!card||card.Type!==2)return;owner.saved.splice(index,1);const freeCard={...card,Id:crypto.randomUUID()};owner.hand.push(freeCard);freePlayCardId.value=freeCard.Id;selection.value={kind:'hand',index:owner.hand.length-1};pendingCrownSavedSpell.value={...pending,cardId:freeCard.Id};inform(`Бесплатно разыграйте «${card.Name}» из сбережений.`);note(`«TheVolkeR» позволяет разыграть «${card.Name}» из сбережений.`)}
