function chooseJexToken(tokenClass:number){const pending=pendingJex.value,target=pending&&board.value.find(unit=>unit.id===pending.targetId&&!unit.dying);if(!pending||!target||tokenClass<0||tokenClass>5)return;target.typeTokens=addTypeToken(target.typeTokens,tokenClass);pending.remaining--;if(pending.remaining)return;const source=board.value.find(unit=>unit.id===pending.sourceId);pendingJex.value=null;if(source){if(pendingEntryTokenGain.value?.id===source.id)pendingEntryTokenGain.value.resolved=true;note(`«Джекс» даёт «${target.card.Name}» три белых жетона типажа.`);finishEntryFollowup(source)}}
