function startTurn(){if(initialLocalTurnPending.value){initialLocalTurnPending.value=false;const p=player.value;newHandCards.value=[];handDrawStart.value=p.hand.length;overLimit.value=Math.max(0,p.hand.length-p.limit);chosenDiscard.value=[];screen.value='game';return}if(localTurnStartResolved.value){localTurnStartResolved.value=false;const p=player.value,handSize=localTurnHandSize.value;newHandCards.value=p.hand.map((_,index)=>index).slice(handSize);handDrawStart.value=handSize;overLimit.value=Math.max(0,p.hand.length-p.limit);chosenDiscard.value=[];if(!p.hand.length)pendingStartTurnBurns.value=0;screen.value='game';note(`${p.name}: ${p.mana} маны и ${p.energy} энергии.`);return}newHandCards.value=[];const handSize=player.value.hand.length;handDrawStart.value=handSize;const p=player.value,owned=board.value.filter(u=>u.owner===current.value),sources=board.value.filter(u=>!u.dying&&(!u.flippedTurns||u.card.Name==='Буня')&&(u.owner===current.value||startTurnEffect(unitDescription(u))?.scope==='every-turn'));p.played=false;p.burnedThisTurn=false;resolveStartTurnStages(()=>owned.forEach(u=>{u.attacks=0;u.abilityUsed=false;if(u.item?.Name==='Щит')u.shield=true}),()=>sources.forEach(u=>{if(screen.value==='winner')return;const effect=startTurnEffect(unitDescription(u)),owner=players.value[u.owner];if(u.card.Name==='Дедруби'){const targets=weakestCreatureTargets(board.value,u.id);if(targets.length===1)kill(targets[0],{burn:true});else if(targets.length>1)pendingDedrubi.value.push({owner:u.owner,sourceId:u.id});return}if(u.card.Name==='Депрессивная Жопа'){resolveDepressiveJawStartTurn(owner);return}if(u.card.Name==='Буня'){const flipped=board.value.filter(card=>card.flippedTurns>0&&!card.dying).length;updateHandLimit(owner,flipped);owner.mana+=flipped;if(flipped)note(`«Буня»: +${flipped} к лимиту руки и мане за перевёрнутые карты.`)}if(!effect)return;for(const operation of effect.operations){if(operation.kind==='draw')for(let i=0;i<operation.count;i++)draw(owner);else if(u.ow