function toggleDiscard(i:number){if(chosenDiscard.value.includes(i)){chosenDiscard.value=chosenDiscard.value.filter(n=>n!==i);return}if(optionalDiscardCount.value&&chosenDiscard.value.length>=optionalDiscardCount.value)return inform(`Можно выбрать не больше ${optionalDiscardCount.value} карт.`);chosenDiscard.value=[...chosenDiscard.value,i]}
