function chooseNewcomersSpell(index:number){const owner=pendingNewcomers.value,card=owner===null?null:players.value[owner].hand[index];if(owner===null||card?.Type!==2)return;players.value[owner].hand.splice(index,1);players.value[owner].saved.push(card);pendingNewcomers.value=null;note(`«Новички» сберегают заклинание «${card.Name}» из руки.`)}
function chooseHand(i:number){if(localCoreChoice.value&&localCoreChoice.value.kind!=='hand-limit-discard')return;if(typeof pendingZnakSave!=='undefined'&&pendingZnakSave.value!==null)return chooseZnakSavedCard(i);if(pendingNewcomers.value!==null)return chooseNewcomersSpell(i);if(pendingApril.value||pendingRottenThief.value||pendingCardPayment.value||pendingDiscordDrama.value||pendingCrownSavedSpell.value)return;if(resolveViskassDiscard(i))return;if(ignoreHandClick.value){ignoreHandClick.value=false;return}if(unplayedWarning.value&&warningDiscardMode.value)return toggleWarningDiscard(i);if(pendingStartTurnBurns.value){const card=player.value.hand.splice(i,1)[0];if(!card)return;const burned=recordBurn(player.value,card);if(burned)player.value.burnedThisTurn=true;pendingStartTurnBurns.value--;overLimit.value=Math.max(0,overLimit.value-1);if(!player.value.hand.length)pendingStartTurnBurns.value=0;note(burned?'Карта из руки сожжена.':'«Hameleonew»: карта сберегается вместо сжигания.');return}if(overLimit.value||optionalDiscardCount.value)return toggleDiscard(i);selection.value=selection.value?.kind==='hand'&&selection.value.index===i?null:{kind:'hand',index:i};const c=player.value.hand[i];inform(c.Type===0?'Выберите свой стартовый слот.':c.Type===3?'Выберите свободный нейтральный слот.':c.Type===1?'Выберите существо для предмета.':'Выберите цель заклинания.')}
