function chooseHalfLifeTarget(target?:Unit){const pending=pendingHalfLife.value;if(!pending)return;if(!target||target.card.Type!==0||target.dying||target.flippedTurns||pending.chosen.includes(target.id))return inform('Выберите не перевёрнутое существо.');const text=players.value[current.value].hand[pending.index]?.Description??'';if(clownTargetRequired(current.value,target,text,pending.chosen.map(id=>({id} as Unit)),pending.remaining))return inform('Если возможно, заклинание должно выбрать существо с «Клоуном».');kill(target);pending.chosen.push(target.id);pending.remaining--;if(!pending.remaining){pendingHalfLife.value=null;finishSpell(pending.index,`Уничтожено существ: ${pending.chosen.length}.`)}else inform(`Half-life 3: выберите ещё ${pending.remaining} ${pending.remaining===1?'существо':'существа'}.`)}
