function resolveSpellMove(row:number,col:number){const pending=pendingSpellMove.value,target=pending&&board.value.find(unit=>unit.id===pending.unitId),anySocket=pending?.mode==='any',validType=target&&(anySocket?[0,3].includes(target.card.Type):target.card.Type===0),validSocket=anySocket?row>=0&&row<5&&col>=0&&col<5&&(target?.card.Type!==3||row>0&&row<4):row===enemyRow.value;if(!pending||!target||!validType||target.dying||target.flippedTurns||!validSocket||board.value.some(unit=>unit.row===row&&unit.col===col))return inform(anySocket?'Выберите незанятый допустимый сокет.':'Выберите свободный сокет на стартовом ряду противника.');target.row=row;target.col=col;pendingSpellMove.value=null;finishSpell(pending.index,anySocket?`«${target.card.Name}» перенесено на ${coord(row,col)}.`:`«${target.card.Name}» перенесено на стартовый ряд противника.`)}
