function resolveEntry(id:string,target?:Unit,effectOwner?:number){const source=board.value.find(x=>x.id===id),owner=effectOwner??source?.owner??current.value,operation=source&&entryTargetOperation(unitDescription(source));if(!source||!operation||!target||!entryTargetCandidates(source,operation,owner).some(candidate=>candidate.id===target.id))return inform('Выберите допустимую цель эффекта входа.');if(operation.kind==='take-target-item'&&target.item){transferItem(source,target.item,target);note('«'+source.card.Name+'» забирает предмет у «'+target.card.Name+'».')}else if(operation.kind==='damage-target'){if(clownTargetRequired(owner,target,unitDescription(source)))return inform('Если возможно, выберите существо с «Клоуном».');damage(target,operation.amount,{killer:source});note(`«${source.card.Name}» наносит «${target.card.Name}» ${operation.amount} урона.`)}else if(operation.kind==='stun-target'){if(operation.targetOwner==='enemy'&&clownTargetRequired(owner,target,unitDescription(source)))return inform('Если возможно, выберите существо с Клоуном.');target.stunned+=operation.turns;note(target.card.Name+' оглушено на '+operation.turns+'.')}else if(operation.kind==='give-type-tokens-if-none'){pendingJex.value={sourceId:source.id,targetId:target.id,owner,remaining:operation.count};selection.value=null;return}else if(operation.kind==='gamba-damage-each-creature'){const roll=rollGamba(players.value[owner]);if(roll<=operation.maximumRoll){const count=countCreaturesOnField(board.value.map(unit=>({type:unit.card.Type,dying:unit.dying})));if(count)damage(target,count,{killer:source});note(`«${source.card.Name}»: гамба ${roll} — ${target.card.Name} получает ${count} урона.`)}else note(`«${source.card.Name}»: гамба ${roll} — без эффекта.`)}else if(operation.kind==='return-creature-to-hand'){returnCardToHand(board.value,players.value[target.owner].hand,players.value[target.owner].discard,target.id);note(`«${source.card.Name}» возвращает «${target.card.Name}» в руку.`)}else if(ope