async function play(i:number,row:number,col:number,target?:Unit,playerTarget?:Player,payment?:PaymentMethod,horny?:boolean){if(localMovePending.value)return;if(pendingApril.value||pendingRottenThief.value||pendingStartTurnBurns.value)return;const c=player.value.hand[i];if(!c)return;if(payment===undefined&&cardCost(c)>0&&canUseHealthPayment(c.Type,bloodEmpireActive())){pendingCardPayment.value={index:i,row,col,...(target?{targetId:target.id}:{}),...(playerTarget?{playerTarget:players.value.indexOf(playerTarget)}:{})};selection.value=null;return}if((c.Name==='V1'||c.Name==='Декстергон')&&horny===undefined){pendingV1Horny.value={index:i,row,col,payment,...(target?{targetId:target.id}:{}),...(playerTarget?{playerTarget:players.value.indexOf(playerTarget)}:{})};selection.value=null;return}if((c.Type===0||c.Type===3)&&!localMovePending.value){c.instanceId??=crypto.randomUUID();const seat=current.value;localMovePending.value=true;try{await applyLocalCommand('card.play',{cardInstanceId:c.instanceId,target:{row,col},payment:payment??'mana',...(horny===true?{horny:true}:{})},seat);const placed=board.value.find(unit=>unit.card.instanceId===c.instanceId);if(c.Type===0&&placed)startDrop(placed,true);visual('play');selection.value=null;note(c.Type===0?`${player.value.name} разыгрывает «${c.Name}» в ${coord(row,col)}.`:`${player.value.name} строит «${c.Name}» в ${coord(row,col)}.`);return}catch(error){if((error as {code?:string})?.code==='TURN_CHANGED'){inform('Ход уже изменился.');return}if(!(error as {code?:string})?.code){console.error('Local card play command failed',error);inform('Не удалось разыграть карту.');return}}finally{localMovePending.value=false}}if(c.Type===1&&target&&!localMovePending.value){c.instanceId??=crypto.randomUUID();const seat=current.value;localMovePending.value=true;try{await applyLocalCommand('item.equip',{cardInstanceId:c.instanceId,targetUnitId:target.id,payment:payment??'mana'},seat);visual('play');selection.value=null;note(`«${c.Name}» экипирован на «${target.card.Name}» (${coord(target.row,target.col)}).`);return}catch(error){if((error as {code?:string})?.code==='TURN_CHANGED'){inform('Ход уже изменился.');return}if(!(error as {code?:string})?.code){console.error('Local item equip command failed',error);inform('Не удалось экипировать предмет.');return}}finally{localMovePending.value=false}}if(c.Type===2&&!localMovePending.value){c.instanceId??=crypto.randomUUID();const seat=current.value,cellTarget=Boolean(spellAreaDamage(c.Description)||spellLineBuff(c.Description)!==null),coreTarget=cellTarget?{row,col}:target?{unitId:target.id}:playerTarget?{player:players.value.indexOf(playerTarget)===seat?'self':'opponent'}:undefined;localMovePending.value=true;try{await applyLocalCommand('spell.cast',{cardInstanceId:c.instanceId,payment:payment??'mana',...(coreTarget?{target:coreTarget}:{})},seat);visual('spell');selection.value=null;note(`«${c.Name}» применяет заклинание.`);return}catch(error){if((error as {code?:string})?.code==='TURN_CHANGED'){inform('Ход уже изменился.');return}if(!(error as {code?:string})?.code){console.error('Local spell command failed',error);inform('Не удалось применить заклинание.');return}}finally{localMovePending.value=false}}if(!spend(c,payment))return
  if(c.Type===0){if(!isHome(row,current.value)){refund(c,payment);return inform('Существо ставится только на свой стартовый ряд.')}if(at(row,col)&&!push(row,col)){refund(c,payment);return inform('Выталкивание заблокировано.')}removeCardForPlay(i);const scoreAdjustment=consumeNextScoreAdjustment(player.value,c.Description),u=unit(c,row,col);u.v1Horny=c.Name==='V1'&&horny===true;board.value.push(u);if(u.v1Horny)hitPlayer(player.value,10);if(c.Name==='Декстергон'&&horny){hitPlayer(player.value,6);applyDextergonHorny(u)}notifyCardPlayed(current.value,c.Type);queueParadiseTargets(current.value);selection.value=null;startDrop(u,true);entry(u,scoreAdjustment);visual('play');note(`${player.value.name} разыгрывает «${c.Name}» в ${coord(row,col)}.`);player.value.played=true;return}
  if(c.Type===3){if(row===0||row===4||target){refund(c,payment);return inform('Здание ставится на свободный нейтральный слот.')}removeCardForPlay(i);const scoreAdjustment=consumeNextScoreAdjustment(player.value,c.Description),building=unit(c,row,col);board.value.push(building);entry(building,scoreAdjustment);notifyCardPlayed(current.value,c.Type);visual('play');note(`${player.value.name} строит «${c.Name}» в ${coord(row,col)}.`);player.value.played=true;selection.value=null;return}
  if(c.Type===1){if(!target||target.card.Type!==0){refund(c,payment);return inform('Предмету нужно выбрать существо.')}if(target.item){refund(c,payment);return inform('У этого существа уже есть предмет.')}removeCardForPlay(i);consumeNextScoreAdjustment(player.value,c.Description);transferItem(target,c);notifyCardPlayed(current.value,c.Type);const entryLimitDelta=entryHandLimitDelta(c.Description);if(entryLimitDelta){updateHandLimit(player.value,entryLimitDelta);note(`«${c.Name}»: лимит руки изменён на ${entryLimitDelta}.`)}visual('play');note(`«${c.Name}» экипирован на «${target.card.Name}» (${coord(target.row,target.col)}).`);player.value.played=true;selection.value=null;return}
