function finishCardPayment(resource:PaymentMethod){const pending=pendingCardPayment.value,card=pending&&player.value.hand[pending.index];if(!pending||!card)return;const cost=cardCost(card);if(resource==='health'&&(!canUseHealthPayment(card.Type,bloodEmpireActive())||player.value.health<=cost))return inform('Недостаточно здоровья для этой оплаты.');if(resource==='mana'&&player.value.mana<cost)return inform(`Недостаточно маны: нужно ${cost}.`);const target=pending.targetId?board.value.find(unit=>unit.id===pending.targetId):undefined,playerTarget=pending.playerTarget===undefined?undefined:players.value[pending.playerTarget];pendingCardPayment.value=null;play(pending.index,pending.row,pending.col,target,playerTarget,resource)}
function finishDiscordDrama(){const pending=pendingDiscordDrama.value,card=pending&&player.value.hand[pending.index],amount=pending?.amount;if(!pending||card?.Name!=='Дискорд драма'||!Number.isInteger(amount)||amount===undefined||amount<0||amount>player.value.mana)return inform('Выберите целое количество маны не больше доступного.');const target=pending.targetId?board.value.find(unit=>unit.id===pending.targetId):undefined;if(pending.targetId&&(!target||target.dying||target.flippedTurns))return inform('Цель «Дискорд драмы» больше недоступна.');if(pending.playerTarget!==undefined&&(!pending.scoreMet||pending.playerTarget!==1-current.value))return inform('Игрок может быть целью только при выполненном счёте.');const effect=discordDramaEffect(card.Description,amount,pending.playerTarget===undefined?'card':'player',player.value.hand.length,player.value.nextScoreAdjustment);player.value.mana-=amount;const dealt=effect.damage;if(target)damage(target,dealt);else hitPlayer(players.value[pending.playerTarget!],dealt);pendingDiscordDrama.value=null;finishSpell(pending.index,`«Дискорд драма»: потрачено ${amount} маны, нанесено ${dealt} урона.`)}
function finishRose(){const pending=pendingRose.value,card=pending&&player.value.hand[pending.index],target=pending&&board.value.find(unit=>unit.id===pending.targetId&&!unit.dying&&!unit.flippedTurns);if(!pending||card?.Name!=='Роза зло'||!target||!Number.isInteger(pending.amount)||pending.amount<0||pending.amount>player.value.health-1)return inform('Выберите целое количество здоровья, оставив минимум 1.');hitPlayer(player.value,pending.amount);damage(target,pending.amount);pendingRose.value=null;finishSpell(pending.index,`«Роза зло» тратит ${pending.amount} здоровья и наносит столько же урона «${target.card.Name}».`)}
