function animateUnitMove(u:Unit,row:number,col:number){const source=document.querySelector<HTMLElement>(`.slot[data-row="${u.row}"][data-col="${u.col}"]`),target=document.querySelector<HTMLElement>(`.slot[data-row="${row}"][data-col="${col}"]`);if(!source||!target)return false;const from=source.getBoundingClientRect(),to=target.getBoundingClientRect();u.moving=true;unitMoveActive.value=false;unitMovePreview.value={card:u.card,left:from.left+from.width/2,top:from.top+from.height/2,dx:to.left+to.width/2-(from.left+from.width/2),dy:to.top+to.height/2-(from.top+from.height/2),width:from.width,height:from.height};requestAnimationFrame(()=>requestAnimationFrame(()=>unitMoveActive.value=true));window.setTimeout(()=>{u.moving=false;unitMoveActive.value=false;unitMovePreview.value=null},520);return true}
async function move(id:string,row:number,col:number,animate=true){
  if(localMovePending.value)return
  const seat=current.value
  const initial=board.value.find(unit=>unit.id===id)
  if(!initial||!active(initial))return
  if(movementIsBlocked(movementLock.value,seat))return inform('В этот ход существа не могут передвигаться.')
  if(!canMove(initial,row,col)||at(row,col))return inform('Можно идти только на соседний свободный слот.')
  if(player.value.energy<effectiveUnitSpeed(initial))return inform(`Нужно ${effectiveUnitSpeed(initial)} энергии.`)
  localMovePending.value=true
  try{
    const {applyCommand}=await loadGameCore()
    const unit=board.value.find(candidate=>candidate.id===id)
    if(current.value!==seat||!unit||!active(unit)||movementIsBlocked(movementLock.value,seat)||!canMove(unit,row,col)||at(row,col)||players.value[seat].energy<effectiveUnitSpeed(unit))return
    const from={row:unit.row,col:unit.col}
    const triggeredTurret=unit.card.Type===0&&board.value.find(candidate=>candidate.card.Name==='Турель'&&!candidate.dying&&!adjacent(candidate,unit.row,unit.col)&&adjacent(candidate,row,col))
    const doggoCount=effectiveUnitSpeed(unit)>=1?board.value.filter(candidate=>candidate.card.Name==='Догго'&&candidate.id!==unit.id&&!candidate.dying).length:0
    const hadWheat=unit.card.Type===0&&wheatTokens.value.some(token=>token.row===row&&token.col===col)
    const basil=unit.card.Name==='Базилик'&&unit.owner!==seat&&!unit.flippedTurns&&!unit.dying
    const wasAnimated=animate&&animateUnitMove(unit,row,col)
    const result=(await applyLocalCommand('unit.move',{unitId:id,to:{row,col}},seat)).state
    const moved=board.value.find(candidate=>candidate.id===id)
    if(wasAnimated&&moved){moved.moving=true;window.setTimeout(()=>moved.moving=false,520)}else if(!animate&&moved)startDrop(moved,false)
    if(doggoCount)visual('buff');visual('move');selection.value=null
    if(hadWheat)note(`«${unit.card.Name}» получает 1 ману за чёрный жетон.`)
    if(basil)note('«Базилик» берёт карту за передвижение не в ход владельца.')
    note(`«${unit.card.Name}» передвигается в ${coord(row,col)}${doggoCount?` — Догго получает +1 ко всем статам (${doggoCount}).`:'.'}${triggeredTurret?' Турель наносит 2 урона.':''}`)
  }catch(error){console.error('Local move command failed',error);inform('Не удалось выполнить перемещение.')}
  finally{localMovePending.value=false}
}
