function hitPlayer(p:Player,n:number){p.health=Math.max(0,p.health-n);if(!p.health){winner.value=winnerWhenPlayerFalls(players.value.indexOf(p) as 0|1);screen.value='winner'}}
function tickBirdliDeathFlip(u:Unit,owner:Player){u.flippedTurns--;if(u.flippedTurns>0){note(`«Бёрдли» остаётся перевёрнутым ещё ${u.flippedTurns} хода.`);return}const index=board.value.findIndex(card=>card.id===u.id);if(index>=0)board.value.splice(index,1);owner.discard.push(u.card);if(u.item)owner.discard.push(u.item);note('«Бёрдли» сбрасывается после переворота.')}
function tickFlippedCards(owner:number){board.value.filter(u=>u.owner===owner&&u.flippedTurns>0&&!u.dying).forEach(u=>{if(u.birdliDeathFlip){tickBirdliDeathFlip(u,players.value[owner]);return}const tick=flipTimerTicks(unitDescription(u))?tickFlipAtOwnerEnd(u.health,u.flippedTurns):{flippedTurns:u.flippedTurns,dies:false,reveals:false};u.flippedTurns=tick.flippedTurns;if(tick.flippedTurns>0)note(`Рубашка в ${coord(u.row,u.col)} остаётся ещё на ${u.flippedTurns} ход.`);else if(tick.dies){note(`Перевёрнутая карта «${u.card.Name}» погибает по окончании срока.`);kill(u)}else if(tick.reveals)note(`«${u.card.Name}» раскрывается в ${coord(u.row,u.col)}.`)})}
function resolveEndTurnEffects(owner:number){const sources=board.value.filter(unit=>!unit.dying&&!unit.flippedTurns);for(const unit of sources){if(unit.card.Name==='Аква'&&unit.owner===owner){const amount=1+typeTokenCount(unit,3);hitPlayer(players.value[1-unit.owner],amount);unit.typeTokens??=[0,0,0,0,0,0];unit.typeTokens[3]=(unit.typeTokens[3]||0)+1;note(`«Аква» наносит ${amount} урона противнику и получает жетон типажа.`)}if(unit.card.Name==='Бункерный паук'){const targets=board.value.filter(target=>target.card.Type===0&&!target.dying&&!target.flippedTurns&&Math.max(Math.abs(target.row-unit.row),Math.abs(target.col-unit.col))===1);targets.forEach(target=>Object.assign(target,applyCombatStatChanges(target,0,-1)));if(targets.length)note(`«Бункерный паук»: −1 к скорости ${targets.length} существ вокруг.`)}if(screen.value==='winner')return}}
function finishTurnLocally(){resolveEndTurnEffects(current.value);if(screen.value==='winner')return;expireCardPlayBuffs();const p=player.value,turnIndex=(round.value-1)*2+current.value;expireHandLimitEffects(p,turnIndex);board.value.filter(u=>temporaryHealthExpiresAtTurn(u.temporaryHealthExpiresAt,turnIndex)&&u.temporaryHealth>0&&!u.dying).forEach(u=>{Object.assign(u,expireTemporaryHealthBuff(u));u.temporaryHealthExpiresAt=0;if(u.health<=0)kill(u);else note(`Временное здоровье «${u.card.Name}» заканчивается.`)});board.value.filter(u=>u.owner===current.value&&u.temporaryAttack>0&&!u.dying).forEach(u=>{Object.assign(u,expireTemporaryAttack(u));note(`Временное усиление атаки «${u.card.Name}» заканчивается.`)});board.value.filter(u=>u.owner===current.value&&u.expiresAtTurnEnd&&!u.dying).forEach(kill);resetDoggoBuffs();p.mana=0;p.energy=0;board.value.filter(u=>u.owner===current.value&&u.stunned>0&&!u.dying).forEach(u=>u.stunned=Math.max(0,u.stunned-1));tickFlippedCards(current.value);if(movementIsBlocked(movementLock.value,current.value))movementLock.value=null;current.value=1-current.value;if(current.value===0)round.value++;screen.value='handoff'}
function applyLocalEndTurnOption(data:Record<string,unknown>){if(data.option==='discard_and_decrease_limit'){const owner=player.value,ids=data.discardedCardInstanceIds as string[];ids.forEach(id=>{const index=owner.hand.findIndex(card=>card.instanceId===id);if(index>=0)owner.discard.push(owner.hand.splice(index,1)[0])});updateHandLimit(owner,-1)}else if(data.option==='increase_limit_after_round_5')updateHandLimit(player.value,1)}
async function finishTurn(data:Record<string,unknown>={}){if(localMovePending.value)return;const commandData=!player.value.played&&!data.option?{option:'no_penalty'}:data;const seat=current.value;localTurnHandSize.value=players.value[1-seat]?.hand.length??0;localMovePending.value=true;try{const result=await applyLocalCommand('turn.end',commandData,seat);localTurnStartResolved.value=true;selection.value=null;if(screen.value!=='winner')screen.value='handoff';for(const event of result.events)if(event.type==='end-turn.effect')note('Срабатывает эффект в конце хода.')}catch(error){if((error as {code?:string})?.code==='UNSUPPORTED_EFFECT'){applyLocalEndTurnOption(commandData);finishTurnLocally();return}console.error('Local end-turn command failed',error);inform('Не удалось завершить ход.')}finally{localMovePending.value=false}}
function resetWarningState(){unplayedWarning.value=false;warningDiscardMode.value=false;warningSelectedDiscards.value=[];discardAnimating.value=false}
function cancelNoPlayWarning(){resetWarningState()}
function openDiscardWarning(){warningDiscardMode.value=true;warningSelectedDiscards.value=[]}
function backFromDiscardWarning(){warningDiscardMode.value=false;warningSelectedDiscards.value=[]}
function toggleWarningDiscard(index:number){if(discardAnimating.value)return;if(warningSelectedDiscards.value.includes(index)){warningSelectedDiscards.value=warningSelectedDiscards.value.filter(item=>item!==index);return}if(warningSelectedDiscards.value.length>=2)return inform('Можно выбрать только две карты.');warningSelectedDiscards.value=[...warningSelectedDiscards.value,index]}
function confirmWarningDiscard(){if(warningSelectedDiscards.value.length<1)return;discardAnimating.value=true;window.setTimeout(()=>{const p=player.value,discardedCardInstanceIds=warningSelectedDiscards.value.map(index=>{const card=p.hand[index];card.instanceId??=crypto.randomUUID();return card.instanceId});note(`${p.name} не разыгрывает карт и сбрасывает выбранные карты.`);resetWarningState();finishTurn({option:'discard_and_decrease_limit',discardedCardInstanceIds})},650)}
function declineNoPlayPenalty(){resetWarningState();finishTurn({option:'no_penalty'})}
function raiseHandLimit(){if(player.value.depressiveHandLimit)return inform('«Депрессивная Жопа» не позволяет менять лимит руки.');if(round.value<5)return;note(`${player.value.name} повышает лимит руки до ${player.value.limit+1}.`);resetWarningState();finishTurn({option:'increase_limit_after_round_5'})}
function end(){if(localMovePending.value)return;if(pendingConveyor.value)return inform('Сначала завершите способность «Конвейерное производство».');if(pendingVismuthChoice.value.length)return inform('Сначала выберите карту для «Висмута Шифера».');if(pendingLibrarianChoice.value)return inform('Сначала выберите карту для «Библиотекаря».');if(pendingHedgehogTargets.value.length)return inform('Сначала выберите цель посмертного эффекта «Ёжика».');if(pendingIntivi.value.length)return inform('Сначала решите, оставить ли предмет «ИНТИВИ» или сбросить его.');if(pendingIndigolit.value)return inform('Сначала завершите эффект «Индиголит».');if(pendingDodep.value)return inform('Сначала завершите эффект «Додеп».');if(pendingZnakSave.value!==null)return inform('Сначала выберите карту для сбережения «Знаком по ебалу».');if(pendingSwarmChoice.value.length)return inform('Сначала выберите награду «Загребущего роя».');if(pendingDedrubi.value.length)return inform('Сначала выберите самое слабое существо для «Дедруби».');if(pendingBurnFlipped.value.length)return inform('Сначала выберите перевёрнутую карту для сжигания.');if(pendingDiscordDrama.value)return inform('Сначала выберите количество маны для «Дискорд драмы».');if(pendingNewcomers.value!==null)return inform('Сначала выберите заклинание для сбережения «Новичков». ');if(pendingCrownMove.value)return inform('Сначала выберите соседний свободный сокет для карты.');if(pendingBuildingMove.value)return inform('Сначала выберите новый сокет здания.');if(pendingSpellMove.value)return inform("Сначала выберите свободный сокет назначения.");if(pendingViskassChoice.value)return inform('Сначала завершите эффект Вискаса.');if(pendingParadiseTargets.value.length)return inform('Сначала выберите существо для «Внешнего рая».');if(pendingBranchTargets.value.length)return inform('Сначала выберите цель для «Веток».');if(pendingCrownSavedSpell.value)return inform('Сначала разыграйте заклинание из сбережений «TheVolkeR».');if(pendingStartTurnShields.value.length)return inform('Сначала выберите существо для щита.');if(pendingFriendlySacrifice.value)return inform('Сначала выберите два своих существа для заклинания.');if(pendingApril.value)return inform('Сначала выберите второе существо для «1 апреля».');if(pendingRottenThief.value)return inform('Сначала выберите ресурс для «Гнилого ворья».');if(pendingHalfLife.value)return inform('Сначала выберите ещё '+pendingHalfLife.value.remaining+' существ для «Half-life 3».');if(pendingIcebergAbility.value)return inform('Выберите эффект способности «Айсберга».');if(pendingV1Horny.value)return inform('Сначала выберите, активировать ли «Хорни 10» для V1.');if(pendingCardPayment.value)return inform('Сначала выберите ресурс для оплаты или отмените розыгрыш.');if(pendingStartTurnBurns.value)return inform('Сначала сожгите указанную карту из руки.');if(optionalDiscardCount.value)return inform('Подтвердите сброс или оставьте все карты.');if(overLimit.value)return inform('Сначала приведите руку к лимиту.');if(selection.value){selection.value=null;return inform('Выбор отменён. Нажмите ещё раз, чтобы завершить ход.')}if(!player.value.played&&(player.value.hand.length>=2||round.value>=5)){unplayedWarning.value=true;warningDiscardMode.value=false;warningSelectedDiscards.value=[];return}finishTurn()}
</script>

<template>
