            <ul class="development-list"><li v-for="card in group.visible" :key="card.Id"><button @click="wikiSelectedCard=card;screen='wiki'" :aria-label="'Открыть карту '+card.Name"><span>{{ card.Name }}</span><small>{{ kind(card.Type) }}</small></button></li></ul>
            <p v-if="!group.visible.length" class="development-empty">Карты не найдены.</p>
          </section>
        </div>
      </section>
      <footer class="home-footer"><strong class="home-brand-text" @pointermove.stop="moveHomeGradient" @pointerleave.stop="homeGradient={x:50,y:50}">BFW</strong><p>Локальная дуэль и онлайн-сражения.</p></footer>
    </section>
    <section v-else-if="screen==='wiki'" class="wiki"><header class="wiki-header"><button class="back" @click="screen='start'">← На главную</button><div><p class="eyebrow">КОЛЛЕКЦИЯ BFW</p><h2>Вики карт</h2><p>{{ wikiCards.length }} из {{ cards.length }} карт</p></div><div class="wiki-filters"><input v-model="wikiSearch" placeholder="Название или текст карты"><select v-model="wikiType"><option value="all">Все типы</option><option value="0">Существа</option><option value="1">Предметы</option><option value="2">Заклинания</option><option value="3">Здания</option></select><select v-model="wikiRarity"><option value="all">Любая редкость</option><option value="0">Обычная</option><option value="1">Редкая</option><option value="2">Легендарная</option></select></div></header><div class="wiki-grid"><article v-for="card in wikiCards" :key="card.Id" class="wiki-card" @click="wikiSelectedCard=card"><img :src="art(card)" :alt="card.Name" loading="lazy" @error="cardImageError"><div><p class="eyebrow">{{ kind(card.Type) }} · {{ ['Обычная','Редкая','Легендарная'][card.Rarity] }}</p><h3>{{ card.Name }}</h3><strong class="development-tag" :class="{ready:!card.Tags?.includes('в разработке')}">{{ card.Tags?.includes('в разработке')?'В разработке':'Готова к игре' }}</strong><p class="wiki-description">{{ card.Description }}</p><div v-if="card.Type===0" class="stats">⚔ {{ card.Attack }} <span>♥ {{ card.Health }}</span><span>⚡ {{ card.Speed }}</span></div><small>Стоимость: {{ card.Cost }}</small></div></article></div><div v-if="wikiSelectedCard" class="wiki-modal-backdrop" @click.self="wikiSelectedCard=null"><article class="wiki-modal"><button class="wiki-modal-close" @click="wikiSelectedCard=null">×</button><img :src="art(wikiSelectedCard)" :alt="wikiSelectedCard.Name" @error="cardImageError"><div><p class="eyebrow">{{ kind(wikiSelectedCard.Type) }} · {{ className(wikiSelectedCard.Class) }} · {{ ['Обычная','Редкая','Легендарная'][wikiSelectedCard.Rarity] }}</p><h2>{{ wikiSelectedCard.Name }}</h2><strong class="development-tag" :class="{ready:!wikiSelectedCard.Tags?.includes('в разработке')}">{{ wikiSelectedCard.Tags?.includes('в разработке')?'В разработке':'Готова к игре' }}</strong><p class="wiki-modal-description">{{ wikiSelectedCard.Description }}</p><div v-if="wikiSelectedCard.Type===0" class="stats wiki-modal-stats">⚔ {{ wikiSelectedCard.Attack }} <span>♥ {{ wikiSelectedCard.Health }}</span><span>⚡ {{ wikiSelectedCard.Speed }}</span></div><p class="wiki-modal-cost">Стоимость: {{ wikiSelectedCard.Cost }}</p></div></article></div></section>
    <section v-else-if="screen==='mode'" class="mode-screen">
      <button class="back" @click="screen='start'">← На главную</button><p class="eyebrow">ВЫБЕРИТЕ РЕЖИМ</p><h2>Как пройдёт партия?</h2>
      <div class="modes">
        <button class="mode-card" :class="{active:canChooseMode,disabled:!canChooseMode}" :disabled="!canChooseMode" @click="openLocalDeckPicker"><b>Локальная игра</b><span>За одним компьютером</span><i>{{ canChooseMode ? 'Доступно' : 'Недоступно' }}</i></button>
        <button class="mode-card" :class="{active:canChooseMode,disabled:!canChooseMode}" :disabled="!canChooseMode" @click="screen='online'"><b>Онлайн-лобби</b><span>Аккаунты, колоды и комнаты</span><i>{{ canChooseMode ? 'Доступно' : 'Недоступно' }}</i></button>
      </div>
      <p v-if="accountLoading||deckLibraryBusy" class="mode-deck-notice" role="status">Проверяем доступные колоды…</p>
