    </section>
    <OnlineLobby v-else-if="screen==='online'" v-model:account="account" v-model:csrf-token="accountCsrfToken" @back="screen='mode'"><template #account-control="{user,connected}"><button class="profile-trigger online-profile-trigger account-identity" aria-label="Открыть профиль" @click="profileOpen=true"><span class="account-state" :class="{connected}"></span><img v-if="user.avatarUrl" :src="user.avatarUrl" alt=""><span v-else class="avatar-fallback" aria-hidden="true">{{ user.displayName.slice(0,1).toLocaleUpperCase('ru') }}</span><div><strong>{{ user.displayName }}</strong><small>@{{ user.username }} · {{ connected ? 'на связи' : 'подключаемся' }}</small></div></button></template></OnlineLobby>
    <section v-else-if="screen==='deck-handoff'" class="handoff"><div class="handoff-card"><p class="eyebrow">КОЛОДА ИГРОКА 1 ГОТОВА</p><h2>Передайте устройство</h2><strong>Игроку 2</strong><p>Игрок 2 выберет колоду, не видя состав соперника.</p><button class="primary" @click="screen='deck-picker'">Выбрать колоду</button></div></section>
    <section v-else-if="screen==='deck-library'" class="deck-library">
      <header class="deck-library-header"><button class="back" @click="screen='start'">← На главную</button><p class="eyebrow">КОЛОДЫ АККАУНТА</p><h2>Мои колоды</h2><p>Собирайте, сохраняйте и выбирайте колоды для локальной игры.</p></header>
      <div v-if="!account" class="deck-account-gate"><h3>Войдите, чтобы открыть редактор</h3><p>Сохранённые колоды привязаны к аккаунту. После входа они будут доступны для локальной игры.</p><button class="primary" @click="screen='online'">Войти / Создать аккаунт</button></div>
      <template v-else>
        <p v-if="deckLibraryError" class="deck-library-error" role="alert">{{ deckLibraryError }}</p><p v-if="deckLibraryBusy" class="deck-library-state" role="status">Загрузка колод…</p>
        <div class="deck-library-grid">
          <article v-for="saved in savedDecks" :key="saved.id" class="saved-deck-tile">
            <div class="card-stack" :aria-label="`Первые карты колоды ${saved.name}`"><img v-for="(card,index) in saved.cards.slice(0,3)" :key="index" :src="art(card)" :alt="card.Name" loading="lazy" @error="cardImageError"></div>
            <h3>{{ saved.name }}</h3><p>{{ saved.cards.length }} карт <span v-if="saved.cards.length!==30">· черновик</span><span v-else>· {{ saved.revision ? `версия ${saved.revision}` : 'готова к игре' }}</span></p>
            <div class="saved-deck-actions"><button class="online-secondary" :disabled="deckLibraryBusy" @click="editSavedDeck(saved.id)">Изменить</button><button class="deck-delete" :disabled="deckLibraryBusy" @click="deckToDelete=saved">Удалить</button></div>
          </article>
          <button class="deck-add-tile" :disabled="deckLibraryBusy" aria-label="Создать новую колоду" @click="createSavedDeck"><span>＋</span><strong>Новая колода</strong></button>
        </div>
      </template>
      <div v-if="deckToDelete" class="deck-modal-backdrop" @click.self="deckToDelete=null"><section class="deck-confirm-modal" role="dialog" aria-modal="true" aria-labelledby="deck-delete-title"><button class="deck-modal-close" aria-label="Закрыть" @click="deckToDelete=null">×</button><p class="eyebrow">УДАЛЕНИЕ КОЛОДЫ</p><h3 id="deck-delete-title">Удалить «{{ deckToDelete.name }}»?</h3><p>Колоду нельзя будет восстановить.</p><div class="deck-confirm-actions"><button class="online-secondary" @click="deckToDelete=null">Отмена</button><button class="deck-delete" :disabled="deckLibraryBusy" @click="confirmDeleteDeck">Удалить колоду</button></div></section></div>
    </section>
    <section v-else-if="screen==='deck-picker'" class="deck-library">
      <header class="deck-library-header"><button class="back" @click="screen='mode'">← К режимам</button><p class="eyebrow">ЛОКАЛЬНАЯ ИГРА · ИГРОК {{ builderPlayer+1 }}</p><h2>Выберите колоду</h2><p>{{ account ? 'Колода из вашего аккаунта' : 'Стартовые колоды доступны без аккаунта' }}. Игрок 2 выберет свою после передачи устройства.</p></header>
      <p v-if="deckLibraryError" class="deck-library-error" role="alert">{{ deckLibraryError }}</p><p v-if="deckLibraryBusy" class="deck-library-state" role="status">Загрузка колод…</p><p v-if="!deckLibraryBusy&&!localDeckChoices.length" class="deck-library-state">Сохранённых колод нет. Создайте её в редакторе колод.</p>
      <div class="deck-library-grid">
        <button v-for="choice in localDeckChoices" :key="choice.id" class="saved-deck-tile deck-choice" :disabled="choice.playable===false||!validateDeck(choice.cards.map(card=>card.Id),cards)" @click="chooseLocalDeck(choice)"><div class="card-stack"><img v-for="(card,index) in choice.cards.slice(0,3)" :key="index" :src="art(card)" :alt="card.Name" loading="lazy" @error="cardImageError"></div><h3>{{ choice.name }}</h3><p>{{ choice.cards.length }} карт</p><strong>{{ choice.playable!==false&&validateDeck(choice.cards.map(card=>card.Id),cards) ? 'Выбрать колоду' : 'Нужны 30 подходящих карт' }}</strong></button>
      </div>
    </section>
    <section v-else-if="screen==='deck'" class="deck-builder"><header class="deck-header"><button class="back" @click="screen='deck-library'">← К колодам</button><div><p class="eyebrow">РЕДАКТОР КОЛОД</p><h2>Редактирование</h2><label class="deck-name-field">Название колоды<input v-model="deckTitle" aria-label="Название колоды" maxlength="64" required></label></div><div class="deck-actions"><button class="primary" :disabled="deckLibraryBusy" @click="saveDeckAndExit">Сохранить и выйти</button></div></header><div class="deck-status"><b>{{ deck.length }} / 30</b><span :class="{ready:deckRarities[0]===15}">Обычные {{ deckRarities[0] }} / 15</span><span :class="{ready:deckRarities[1]===12}">Редкие {{ deckRarities[1] }} / 12</span><span :class="{ready:deckRarities[2]===3}">Легендарные {{ deckRarities[2] }} / 3</span><span>Типажи: {{ deckClasses.map(className).join(', ') || '—' }}</span></div><p v-if="deckMessage" class="deck-message">{{ deckMessage }}</p><div class="deck-layout"><aside class="deck-list" :class="{dragging:deckDropActive}" @dragover.prevent @drop.prevent="dropCardIntoDeck"><div class="deck-list-title"><div><b>Ваша колода</b><span>{{ deckUnique.length }} разных карт</span></div><button class="reset-deck" @click="resetDeck">Сбросить колоду</button></div><p class="drop-hint">Перетащите карту из каталога сюда</p><div class="deck-cards"><article v-for="card in deckUnique" :key="card.Id" class="deck-card" draggable="true" @mouseenter="deckHoverCard=card" @mouseleave="deckHoverCard=null" @dragstart="startDeckCardDrag($event,card)" @dragend="endCardDrag" @click="removeFromDeck(card)"><img :src="art(card)" :alt="card.Name" loading="lazy" @error="cardImageError"><div><b>{{ card.Name }}</b><small>{{ className(card.Class) }} · {{ ['Обычная','Редкая','Легендарная'][card.Rarity] }}</small></div><em>×{{ copiesOf(card) }}</em><button title="Убрать одну копию">−</button></article></div><div class="deck-trash" :class="{dragging:trashDropActive}" @dragover.prevent @drop.prevent="dropCardToTrash">Перетащите карту сюда, чтобы выбросить одну копию</div></aside><div class="card-catalog"><div class="catalog-controls"><input v-model="deckSearch" placeholder="Найти карту"><select v-model="deckFilterClass"><option value="all">Все типажи</option><option v-for="(_,index) in ['Тфер','Симп','Метрокоп','Токсик','Темщик','Гэмблер']" :key="index" :value="String(index)">{{ className(index) }}</option></select><select v-model="deckFilterRarity"><option value="all">Любая редкость</option><option value="0">Обычная</option><option value="1">Редкая</option><option value="2">Легендарная</option></select></div><p class="catalog-count">{{ deckCards.length }} карт доступно. Перетащите карту в вашу колоду.</p><div class="catalog-grid"><button v-for="card in deckCards" :key="card.Id" class="catalog-card" :class="{full:card.Rarity<2&&copiesOf(card)>=2}" draggable="true" @mouseenter="deckHoverCard=card" @mouseleave="deckHoverCard=null" @dragstart="startCardDrag($event,card)" @dragend="endCardDrag"><img :src="art(card)" :alt="card.Name" loading="lazy" @error="cardImageError"><span>{{ card.Cost }}</span><b>{{ card.Name }}</b><small>{{ className(card.Class) }} · {{ ['Обычная','Редкая','Легендарная'][card.Rarity] }}</small><em v-if="copiesOf(card)">×{{ copiesOf(card) }}</em></button></div></div></div><aside v-if="deckHoverCard" class="deck-inspector"><img :src="art(deckHoverCard)" :alt="deckHoverCard.Name" @error="cardImageError"><div><p class="eyebrow">{{ kind(deckHoverCard.Type) }} · {{ className(deckHoverCard.Class) }} · {{ ['Обычная','Редкая','Легендарная'][deckHoverCard.Rarity] }}</p><h3>{{ deckHoverCard.Name }}</h3><p class="deck-description">{{ deckHoverCard.Description }}</p><div v-if="deckHoverCard.Type===0" class="stats">⚔ {{ deckHoverCard.Attack }} <span>♥ {{ deckHoverCard.Health }}</span><span>⚡ {{ deckHoverCard.Speed }}</span></div><small>Стоимость: {{ deckHoverCard.Cost }}</small></div></aside></section>
    <section v-else-if="screen==='handoff'" class="handoff"><div class="handoff-card"><p class="eyebrow">РАУНД {{ round }}</p><h2>Передайте устройство</h2><strong>{{ players[current]?.name }}</strong><p>Подготовьте свой ход. Карты противника останутся скрыты.</p><button class="primary" @click="startTurn">Начать ход</button></div></section>
    <section v-else-if="screen==='winner'" class="winner"><p class="eyebrow">ПАРТИЯ ОКОНЧЕНА</p><h2>{{ players[winner]?.name }} побеждает</h2><p>Здоровье противника опустилось до нуля.</p><button class="primary" @click="screen='start'">На главную</button></section>
    <section v-else class="game" @copy.prevent>
      <aside class="game-sidebar" aria-label="Раунд и ресурсы"><header class="game-header"><div class="round"><span>РАУНД</span><b>{{ round }}</b></div></header>
      <div class="resources"><span>✦ Мана <b>{{ player.mana }}</b></span><span>⚡ Энергия <b>{{ player.energy }}</b></span><span>КД {{ player.deck.length }}</span><span>КС {{ player.discard.length }}</span><span>КСК {{ player.burned.length }}</span><span>СБ {{ player.saved.length }}</span></div></aside><div v-if="toast" class="toast">{{ toast }}</div><div v-if="pendingIcebergAbility" class="turn-warning-backdrop"><section class="turn-warning" role="dialog" aria-modal="true"><div class="warning-icon">⚫</div><p class="eyebrow">«АЙСБЕРГ»</p><h2>Выберите эффект способности</h2><div class="warning-actions"><button v-if="!localCoreChoice" class="warning-secondary" @click="pendingIcebergAbility=null">Отмена</button><button class="warning-primary" @click="resolveIcebergAbility('draw')">Взять карту</button><button class="warning-primary" @click="resolveIcebergAbility('limit')">Лимит руки +1</button></div></section></div><div v-if="pendingRose" class="turn-warning-backdrop"><section class="turn-warning" role="dialog" aria-modal="true" aria-labelledby="rose-title"><div class="warning-icon">♥</div><p class="eyebrow">«РОЗА ЗЛО»</p><h2 id="rose-title">Сколько здоровья потратить?</h2><p>Урон выбранной карте будет равен потраченному здоровью. Доступно: {{ Math.max(0, player.health - 1) }}.</p><input type="number" min="0" :max="Math.max(0, player.health - 1)" step="1" v-model.number="pendingRose.amount" aria-label="Количество здоровья"><div class="warning-actions"><button class="warning-primary" :disabled="!Number.isInteger(pendingRose.amount)||pendingRose.amount<0||pendingRose.amount>player.health-1" @click="finishRose">Потратить здоровье</button></div></section></div><div v-if="pendingDiscordDrama" class="turn-warning-backdrop"><section class="turn-warning" role="dialog" aria-modal="true" aria-labelledby="discord-drama-title"><div class="warning-icon">✦</div><p class="eyebrow">«ДИСКОРД ДРАМА»</p><h2 id="discord-drama-title">Сколько маны потратить?</h2><p>От 0 до {{ player.mana }}. Урон: {{ pendingDiscordDrama.amount * (pendingDiscordDrama.playerTarget!==undefined && pendingDiscordDrama.scoreMet ? 2 : 1) }}.</p><input type="number" min="0" :max="player.mana" step="1" v-model.number="pendingDiscordDrama.amount" aria-label="Количество маны"><div class="warning-actions"><button class="warning-primary" :disabled="!Number.isInteger(pendingDiscordDrama.amount)||pendingDiscordDrama.amount<0||pendingDiscordDrama.amount>player.mana" @click="finishDiscordDrama">Потратить ману</button></div></section></div><div v-if="pendingCardPayment&&pendingPaymentCard" class="turn-warning-backdrop"><section class="turn-warning" role="dialog" aria-modal="true" aria-labelledby="payment-title"><div class="warning-icon">♥</div><p class="eyebrow">«ИМПЕРИЯ КРОВИ»</p><h2 id="payment-title">Оплатить «{{ pendingPaymentCard.Name }}»</h2><p>Стоимость: {{ cardCost(pendingPaymentCard) }}. Выберите ресурс для оплаты.</p><div class="warning-actions"><button class="warning-secondary" :disabled="player.mana<cardCost(pendingPaymentCard)" @click="finishCardPayment('mana')">{{ cardCost(pendingPaymentCard) }} маны</button><button class="warning-primary" :disabled="player.health<=cardCost(pendingPaymentCard)" @click="finishCardPayment('health')">{{ cardCost(pendingPaymentCard) }} здоровья</button></div><button class="warning-cancel warning-cancel-bottom" @click="cancelCardPayment">Отмена</button></section></div><div v-if="unplayedWarning" class="turn-warning-backdrop"><section class="turn-warning" :class="{choosing:warningDiscardMode}" role="dialog" aria-modal="true" aria-labelledby="turn-warning-title"><template v-if="!warningDiscardMode"><div class="warning-icon">!</div><p class="eyebrow">ПЕРЕД ЗАВЕРШЕНИЕМ ХОДА</p><h2 id="turn-warning-title">Карты не разыграны</h2><p>Вы можете сбросить до 2 карт из руки и понизить лимит карт на 1.<br>Начиная с 5 ого раунда вы можете повысить свой лимит на 1.</p><div class="warning-actions"><button class="warning-secondary" @click="declineNoPlayPenalty">Закончить без штрафа</button><span class="limit-tooltip" :title="round<5?'с 5ого раунда':''"><button class="warning-secondary" :disabled="round<5" @click="raiseHandLimit">Лимит руки +1</button></span><button v-if="player.hand.length>=1" class="warning-primary" @click="openDiscardWarning">Сбросить карты</button></div><button class="warning-cancel warning-cancel-bottom" @click="cancelNoPlayWarning">Отмена</button></template><template v-else><div class="warning-icon">2</div><p class="eyebrow">ВЫБЕРИТЕ КАРТЫ В РУКЕ</p><h2 id="turn-warning-title">Сбросьте до двух карт</h2><p>Выберите карты для сброса.</p><strong class="discard-counter">Выбрано: {{ warningSelectedDiscards.length }} / 2</strong><div class="warning-actions"><button class="warning-cancel" :disabled="discardAnimating" @click="backFromDiscardWarning">Назад</button><button class="warning-primary" :disabled="warningSelectedDiscards.length<1||discardAnimating" @click="confirmWarningDiscard">{{ discardAnimating?'Сброс…':'Подтвердить сброс' }}</button></div></template></section></div>
      <div v-if="pendingBurnFlipped.length" class="discard-bar"><b>{{ players[pendingBurnFlipped[0]]?.name }}: выберите одну перевёрнутую карту для сжигания «Горящим тромбиком».</b></div><div v-if="pendingCrownMove" class="discard-bar"><b>«Грави пушка»: выберите соседний свободный сокет.</b></div><div v-if="pendingBuildingMove" class="discard-bar"><b>«Джон Роблокс»: выберите соседний свободный нейтральный сокет.</b></div><div v-if="pendingSpellMove" class="discard-bar"><b>«Брутфорс»: выберите свободный сокет на стартовом ряду противника.</b></div><div v-if="pendingFriendlySacrifice" class="discard-bar"><b>«Бей своих чтобы чужие боялись»: выберите второе своё существо для уничтожения.</b></div><div v-if="pendingStartTurnShields.length" class="discard-bar"><b>«{{ board.find(unit=>unit.id===pendingStartTurnShields[0])?.card.Name }}»: выберите существо в соседнем сокете для щита.</b></div><div v-if="pendingStartTurnBurns||overLimit||optionalDiscardCount" class="discard-bar"><b v-if="pendingStartTurnBurns">«Рокочущий рыцарь»: сожгите {{ pendingStartTurnBurns }} карту из руки.</b><b v-else>{{ overLimit?'Лимит руки превышен.':`Можно сбросить до ${optionalDiscardCount} карт.` }}</b><span v-if="!pendingStartTurnBurns">{{ overLimit?`Выберите ${overLimit} карт: ${chosenDiscard.length}/${overLimit}`:`Выбрано: ${chosenDiscard.length}/${optionalDiscardCount}` }}</span><button v-if="!pendingStartTurnBurns" @click="confirmDiscard">{{ overLimit?'Сбросить':'Сбросить выбранные' }}</button><button v-if="optionalDiscardCount&&!overLimit" @click="skipOptionalDiscard">Оставить все</button></div>
<div v-if="pendingRottenThief" class="turn-warning-backdrop"><section class="turn-warning" role="dialog" aria-modal="true" aria-labelledby="rotten-thief-title"><h2 id="rotten-thief-title">Гнилое ворьё</h2><p>Выберите ресурс, который заберёте у противника. Если его меньше указанного количества, забирается весь остаток.</p><div class="warning-actions"><button class="warning-primary" @click="chooseRottenThief('mana')">До 2 маны · у противника {{ players[1-current].mana }}</button><button class="warning-primary" @click="chooseRottenThief('energy')">До 4 энергии · у противника {{ players[1-current].energy }}</button></div></section></div><div v-if="pendingApril" class="turn-warning-backdrop"><section class="turn-warning" role="dialog" aria-modal="true" aria-labelledby="april-title"><h2 id="april-title">1 апреля</h2><p>Выберите второе существо, чтобы обменять параметры и жетоны.</p><div class="warning-actions"><button v-for="target in board.filter(unit=>unit.card.Type===0&&!unit.dying&&unit.id!==pendingApril.firstId)" :key="target.id" class="warning-primary" @click="chooseAprilTarget(target.id)">{{ target.card.Name }} · ⚔️ {{ target.attack }} · ♥ {{ target.health }}/{{ target.maxHealth }} · ⚡ {{ effectiveUnitSpeed(target) }}</button></div></section></div><div v-if="pendingDedrubi.length" class="turn-warning-backdrop"><section class="turn-warning" role="dialog" aria-modal="true" aria-labelledby="dedrubi-title"><h2 id="dedrubi-title">Дедруби</h2><p>Выберите одно из самых слабых существ по текущему здоровью, чтобы сжечь его.</p><div class="warning-actions"><button v-for="target in weakestCreatureTargets(board,pendingDedrubi[0].sourceId)" :key="target.id" class="warning-primary" @click="chooseDedrubiTarget(target.id)">{{ target.card.Name }} · ♥ {{ target.health }}</button></div></section></div><div v-if="pendingBranchTargets.length" class="turn-warning-backdrop"><section class="turn-warning" role="dialog" aria-modal="true" aria-labelledby="branch-title"><h2 id="branch-title">Ветки</h2><p>Выберите вражескую карту, чтобы нанести ей 1 урон.</p><div class="warning-actions"><button v-for="target in board.filter(unit=>unit.owner!==pendingBranchTargets[0]&&!unit.dying)" :key="target.id" class="warning-primary" @click="chooseBranchTarget(target.id)">{{ target.card.Name }}</button></div></section></div><div v-if="pendingDrone.length&&selection===null&&!pendingDiscordDrama&&!pendingRose&&!pendingRottenThief&&!pendingViskassChoice&&!pendingJex&&!pendingApril&&!pendingHalfLife&&!pendingDedrubi.length&&!pendingStartTurnShields.length&&!pendingStartTurnBurns&&pendingNewcomers===null&&!pendingBurnFlipped.length&&!pendingSentCroix.length&&!pendingParadiseTargets.length&&!pendingBranchTargets.length&&!pendingFriendlySacrifice&&!pendingCrownSavedSpell&&!pendingCardPayment&&!pendingV1Horny&&!pendingSpellMove&&!pendingBuildingMove" class="turn-warning-backdrop"><section class="turn-warning" role="dialog" aria-modal="true" aria-labelledby="drone-title"><h2 id="drone-title">Дрон</h2><p>Выберите до {{ pendingDrone[0].count }} карт из КД общей стоимостью до {{ pendingDrone[0].totalCost }}. Выбрано: {{ pendingDrone[0].selected.length }} / {{ pendingDrone[0].count }}, стоимость {{ pendingDrone[0].cost }}.</p><div class="warning-actions"><button v-for="(card,index) in players[pendingDrone[0].owner].deck" v-if="card.Cost<=pendingDrone[0].totalCost" :key="index" :class="pendingDrone[0].selected.includes(index)?'warning-primary':'warning-secondary'" :disabled="!pendingDrone[0].selected.includes(index)&&(pendingDrone[0].selected.length>=pendingDrone[0].count||card.Cost+pendingDrone[0].cost>pendingDrone[0].totalCost)" @click="toggleDroneCard(index)">{{ card.Name }} · {{ card.Cost }}{{ pendingDrone[0].selected.includes(index)?' ✓':'' }}</button></div><div class="warning-actions"><button class="warning-primary" @click="finishDroneSelection">Отправить в сбережения</button></div></section></div><div v-if="pendingSentCroix.length&&selection===null&&!pendingViskassChoice&&!pendingJex&&!pendingApril&&!pendingHalfLife&&!pendingDedrubi.length&&!pendingStartTurnShields.length&&!pendingStartTurnBurns&&pendingNewcomers===null&&!pendingBurnFlipped.length" class="turn-warning-backdrop"><section class="turn-warning" role="dialog" aria-modal="true" aria-labelledby="sent-croix-title"><h2 id="sent-croix-title">Сент-круа</h2><template v-if="!pendingSentCroix[0].cardId"><p>Выберите самое дёшевое существо из руки.</p><div class="warning-actions"><button v-for="option in sentCroixOptions()" :key="option.index" class="warning-primary" @click="chooseSentCroixCard(option.card.Id)">{{ option.card.Name }} · {{ option.card.Cost }}</button></div></template><template v-else><p>Выберите свободный соседний сокет для {{ players[pendingSentCroix[0].owner].hand.find(card=>card.Id===pendingSentCroix[0].cardId)?.Name }}.</p><div class="warning-actions"><button v-for="slot in sentCroixSockets()" :key="slot.row+':'+slot.col" class="warning-primary" @click="resolveSentCroixSlot(slot.row,slot.col)">{{ slot.row+1 }}, {{ slot.col+1 }}</button></div></template></section></div><div v-if="pendingJex" class="turn-warning-backdrop"><section class="turn-warning" role="dialog" aria-modal="true" aria-labelledby="jex-title"><h2 id="jex-title">Джекс · белые жетоны</h2><p>Выберите типаж для жетона. Осталось: {{ pendingJex.remaining }}.</p><div class="warning-actions"><button v-for="(_,tokenClass) in ['Тфер','Симп','Метрокоп','Токсик','Темщик','Гэмблер']" :key="tokenClass" class="warning-primary" @click="chooseJexToken(tokenClass)">{{ className(tokenClass) }}</button></div></section></div><div v-if="pendingParadiseTargets.length" class="turn-warning-backdrop"><section class="turn-warning" role="dialog" aria-modal="true" aria-labelledby="paradise-title"><h2 id="paradise-title">Внешний рай</h2><p>Выберите своё существо: его затраты энергии на передвижение уменьшатся на 1.</p><div class="warning-actions"><button v-for="target in board.filter(unit=>unit.owner===pendingParadiseTargets[0]&&unit.card.Type===0&&!unit.dying)" :key="target.id" class="warning-primary" @click="chooseParadiseTarget(target.id)">{{ target.card.Name }} · энергия {{ effectiveUnitSpeed(target) }}</button></div></section></div><div v-if="pendingNewcomers!==null" class="turn-warning-backdrop"><section class="turn-warning" role="dialog" aria-modal="true" aria-labelledby="newcomers-title"><h2 id="newcomers-title">Новички</h2><p>Выберите заклинание из руки игрока, которое нужно сберечь.</p><div class="warning-actions"><button v-for="(card,index) in players[pendingNewcomers].hand" v-if="card.Type===2" :key="card.Id+index" class="warning-primary" @click="chooseNewcomersSpell(index)">{{ card.Name }}</button></div></section></div><div v-if="pendingHedgehogTargets.length" class="turn-warning-backdrop"><section class="turn-warning" role="dialog" aria-modal="true" aria-labelledby="hedgehog-title"><h2 id="hedgehog-title">Ёжик · посмертный эффект</h2><p>Выберите цель: она получит 1 урон и −1 к атаке.</p><div class="warning-actions"><button v-for="target in board.filter(unit=>!unit.dying)" :key="target.id" class="warning-primary" @click="chooseHedgehogTarget(target.id)">{{ target.card.Name }} · ♥ {{ target.health }}</button><button v-if="pendingHedgehogTargets[0].row===(pendingHedgehogTargets[0].owner===0?0:4)" class="warning-secondary" @click="chooseHedgehogTarget(undefined,1-pendingHedgehogTargets[0].owner)">Противник · ♥ {{ players[1-pendingHedgehogTargets[0].owner].health }}</button></div></section></div><div v-if="pendingLibrarianChoice" class="turn-warning-backdrop"><section class="turn-warning" role="dialog" aria-modal="true" aria-labelledby="librarian-title"><h2 id="librarian-title">Библиотекарь</h2><p v-if="pendingLibrarianChoice.stage==='cost'">Выберите оплату: 1 мана — обычная, 2 — редкая, 4 — легендарная карта.</p><p v-else-if="pendingLibrarianChoice.stage==='pile'">Выберите колоду для поиска карты.</p><p v-else>Выберите карту редкости {{ pendingLibrarianChoice.cost===1?'обычная':