      <div class="hand-wrap" :class="{'warning-discard-mode':warningDiscardMode}"><div class="hand-title"><div><span>РУКА</span><b>{{player.hand.length}} / {{player.limit}}</b></div><button class="end-turn" @click="end">Закончить ход</button></div><div class="hand" :style="{'--hand-count':player.hand.length}"><button v-for="(card,i) in player.hand" :key="card.Id+i" class="hand-card" :style="{'--hand-order':i,'--draw-delay':Math.max(0,i-handDrawStart)*100+'ms'}" :class="{'drawn-card':newHandCards.includes(i),selected:selection?.kind==='hand'&&selection.index===i,discard:chosenDiscard.includes(i),'warning-discard':warningDiscardMode&&warningSelectedDiscards.includes(i),evaporating:discardAnimating&&warningSelectedDiscards.includes(i),'dragging-source':handDragActive&&draggedHandIndex===i}" @animationend="newHandCards=newHandCards.filter(index=>index!==i)" @pointerdown="newHandCards=[];beginHandDrag($event,i)" @dragstart.prevent @mouseenter="showCardInfo(card,$event)" @mouseleave="hideCardInfo" @focus="showCardInfo(card,$event)" @blur="hideCardInfo" @click="newHandCards=[];chooseHand(i)"><img :src="art(card)" :alt="card.Name" draggable="false" @dragstart.prevent @error="cardImageError"></button></div></div><div v-if="handDragActive&&draggedHandIndex!==null&&player.hand[draggedHandIndex]" class="hand-drag-preview" :class="{snapped:handDragSnap}" :style="{left:handDragPosition.left+'px',top:handDragPosition.top+'px',width:handDragSize.width+'px',height:handDragSize.height+'px'}"><img :src="art(player.hand[draggedHandIndex])" :alt="player.hand[draggedHandIndex].Name" @error="cardImageError"></div>
      <CardInspector ref="cardInspector" />
      <div v-if="pendingCrownSavedSpell" class="discard-bar"><b>{{ pendingCrownSavedSpell.cardId?`Разыграйте «${player.hand.find(card=>card.Id===pendingCrownSavedSpell.cardId)?.Name}».`:`«TheVolkeR»: выберите заклинание из сбережений.` }}</b></div><details v-if="player.saved.length" class="saved-pile" :open="!!pendingCrownSavedSpell"><summary>Сбережения · {{ player.saved.length }}</summary><div><button v-for="(card,index) in player.saved" :key="card.Id+index" @mouseenter="showCardInfo(card,$event)" @mouseleave="hideCardInfo" @focus="showCardInfo(card,$event)" @blur="hideCardInfo" @click="pendingCrownSavedSpell?playCrownSavedSpell(index):takeSavedCard(index)" :disabled="!!pendingCrownSavedSpell&&(!!pendingCrownSavedSpell.cardId||card.Type!==2)">Взять «{{ card.Name }}»</button></div></details>
      <aside class="log"><b>Журнал боя</b><p v-for="item in log" :key="item">{{item}}</p></aside>
    </section>
    <div v-if="profileOpen && account" class="profile-backdrop" @click.self="closeProfile" @keydown.esc="closeProfile"><aside class="profile-drawer" role="dialog" aria-modal="true" aria-labelledby="profile-title"><header><div><p class="eyebrow">АККАУНТ · @{{ account.username }}</p><h2 id="profile-title">Профиль аккаунта</h2></div><button class="profile-close" aria-label="Закрыть профиль" @click="closeProfile">×</button></header><form class="profile-form" @submit.prevent="saveNickname"><label for="profile-nickname">Никнейм</label><input id="profile-nickname" v-model="nicknameDraft" maxlength="32" autocomplete="nickname" required><button class="profile-save" :disabled="profileBusy || nicknameDraft.trim()===account.displayName">Сохранить никнейм</button></form><form class="profile-form" @submit.prevent="changePassword"><h3>Сменить пароль</h3><label for="profile-current-password">Текущий пароль</label><input id="profile-current-password" v-model="currentPassword" type="password" autocomplete="current-password" required><label for="profile-new-password">Новый пароль · не менее 12 символов</label><input id="profile-new-password" v-model="newPassword" type="password" minlength="12" maxlength="128" autocomplete="new-password" required><button class="profile-save" :disabled="profileBusy">Изменить пароль</button></form><section class="profile-avatar-section"><h3>Аватар</h3><label for="profile-avatar-file">JPEG, PNG или WebP, до 5 MiB</label><input id="profile-avatar-file" type="file" accept="image/jpeg,image/png,image/webp" :disabled="profileBusy" @change="uploadProfileAvatar"><img v-if="avatarPreview" class="profile-avatar-preview" :src="avatarPreview" alt="Предпросмотр нового аватара"><button v-if="account.avatarUrl" class="profile-remove-avatar" :disabled="profileBusy" @click="removeProfileAvatar">Удалить аватар</button></section><p v-if="profileMessage" class="profile-message" role="status">{{ profileMessage }}</p><p class="profile-note">Забытый пароль пока нельзя восстановить.</p><button class="profile-logout" :disabled="profileBusy" @click="logoutAccount">Выйти из аккаунта</button></aside></div>
  </main>
</template>












